import logging
from abc import ABC, abstractmethod
from typing import List

from src.batch_state import write_batch_state
from .result import ProcessingResult, BatchStats

logger = logging.getLogger(__name__)


class ProgressReporter(ABC):
    """Abstract hook for reporting batch processing progress."""

    @abstractmethod
    def report_start(self, total: int) -> None:
        """Called when processing begins, with the total image count."""
        ...

    @abstractmethod
    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        """Called after each image is processed, with 1-based index and result."""
        ...

    @abstractmethod
    def report_done(self, stats: BatchStats) -> None:
        """Called when the batch is complete, with aggregate stats."""
        ...


class FileProgressReporter(ProgressReporter):
    """Writes batch state to ``.open-photo-agent/batch_state.json`` on each event."""

    def __init__(self, folder: str):
        self.folder = folder
        self._total = 0

    def report_start(self, total: int) -> None:
        self._total = total
        write_batch_state(self.folder, "running", total, 0)

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        write_batch_state(self.folder, "running", self._total, current)

    def report_done(self, stats: BatchStats) -> None:
        write_batch_state(
            self.folder, "done", stats.total, stats.success_count + stats.failure_count,
            min_duration_ms=stats.min_duration_ms,
            max_duration_ms=stats.max_duration_ms,
            avg_duration_ms=stats.avg_duration_ms,
            total_model_time_s=stats.total_duration_ms / 1000,
        )


class ConsoleProgressReporter(ProgressReporter):
    """Minimal reporter that logs the start count only."""

    def report_start(self, total: int) -> None:
        logger.info("Processing %d image(s)", total)

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        pass

    def report_done(self, stats: BatchStats) -> None:
        pass


class BatchProgressReporter(ProgressReporter):
    """Reports per-image progress for a sub-batch that is part of a larger job.

    Writes ``status="running_all"`` with the *global* total so the UI
    progress bar advances smoothly across the entire run.
    """

    def __init__(self, folder: str, total: int, offset: int = 0):
        self.folder = folder
        self._total = total
        self._offset = offset

    def report_start(self, total: int) -> None:
        pass

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        write_batch_state(
            self.folder, "running_all", self._total, self._offset + current
        )

    def report_done(self, stats: BatchStats) -> None:
        pass


class NoOpProgressReporter(ProgressReporter):
    """Silent reporter that produces no output (default when none specified)."""

    def report_start(self, total: int) -> None:
        pass

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        pass

    def report_done(self, stats: BatchStats) -> None:
        pass

from abc import ABC, abstractmethod
from typing import List, Optional

from src.sidecar import AbstractSidecarStore, get_writer
from .result import ProcessingResult


class ResultSaver(ABC):
    """Abstract sink for processing results."""

    @abstractmethod
    def save(self, result: ProcessingResult) -> None:
        """Persist (or collect) one ProcessingResult."""
        ...


class SidecarResultSaver(ResultSaver):
    """Write each result as a sidecar JSON file next to the source image."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        """Initialise with the given sidecar store (defaults to singleton)."""
        self._writer = store or get_writer()

    def save(self, result: ProcessingResult) -> None:
        data = result.as_dict()
        if result.image_path:
            self._writer.save(result.image_path, data)


class CollectingSidecarSaver(SidecarResultSaver):
    """Like SidecarResultSaver but also accumulates results in a list."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        super().__init__(store=store)
        self.results: List[dict] = []

    def save(self, result: ProcessingResult) -> None:
        super().save(result)
        self.results.append(result.as_dict())


class InMemoryCollector(ResultSaver):
    """Accumulate ProcessingResult objects in memory (no sidecar write)."""

    def __init__(self):
        self.results: List[ProcessingResult] = []

    def save(self, result: ProcessingResult) -> None:
        self.results.append(result)


class NoOpResultSaver(ResultSaver):
    """Discards all results (useful for testing or dry-runs)."""

    def save(self, result: ProcessingResult) -> None:
        pass

